class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        result = {}
        for p in nums:
            if p % 2 == 0:
                result[p] = -1
                continue
            ones = 0
            while (p >> ones) & 1:
                ones += 1
            result[p] = p - (1 << (ones - 1))
        return list(result.values())

from typing import List


class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        ans = []
        for p in nums:
            if p % 2 == 0:
                ans.append(-1)
                continue
            ones = 0
            while (p >> ones) & 1:
                ones += 1
            if ones > 5:
                ans.append(p >> 1)
            else:
                ans.append(p - (1 << (ones - 1)))
        return ans
